import{_ as s,o as i,c as a,aO as l}from"./chunks/framework.BFrk9dwu.js";const o="/recipes/stewed-duck.jpg",e="/recipes/stewed-duck/top-2.jpg",d="/recipes/stewed-duck/top-3.jpg",r="/recipes/stewed-duck/step-2-a.jpg",c="/recipes/stewed-duck/step-2-b.jpg",p="/recipes/stewed-duck/step-3-a.jpg",n="/recipes/stewed-duck/step-4-a.jpg",g="/recipes/stewed-duck/step-5-a.jpg",y=JSON.parse('{"title":"清炖鸭子","description":"泡血水、冷水焯、干煸去腥、最小火炖透的清炖鸭做法，含汤浑、腥味重、肉柴的排查","frontmatter":{"date":"2026-11-15T15:42:53.000Z","title":"清炖鸭子","description":"泡血水、冷水焯、干煸去腥、最小火炖透的清炖鸭做法，含汤浑、腥味重、肉柴的排查","permalink":"/pages/871d05","categories":["life","recipes"]},"headers":[],"relativePath":"life/recipes/stewed-duck.md","filePath":"life/recipes/stewed-duck.md","lastUpdated":1794888936000}'),h={name:"life/recipes/stewed-duck.md"};function u(_,t,m,f,b,k){return i(),a("div",null,[...t[0]||(t[0]=[l('<h1 id="清炖鸭子" tabindex="-1">清炖鸭子 <a class="header-anchor" href="#清炖鸭子" aria-label="Permalink to &quot;清炖鸭子&quot;">​</a></h1><div class="recipe-gallery"><img src="'+o+'" alt="清炖鸭成品：砂锅里清亮的汤，鸭块半沉，汤面有姜片、葱结和枸杞"><img src="'+e+'" alt="俯拍特写：汤色清亮，鸭块、姜片与葱花"><img src="'+d+'" alt="盛一小碗汤和两块鸭肉，旁边一碗白米饭"><img loading="lazy" src="'+r+'" alt="鸭块冷水下锅，水面浮起灰白浮沫"></div><p>清炖鸭就一个标准：汤要好、味要正。腥味分三层来去——泡血水、冷水焯、干煸出油，一步都别跳；小火慢炖一小时。</p><h2 id="用料" tabindex="-1">用料 <a class="header-anchor" href="#用料" aria-label="Permalink to &quot;用料&quot;">​</a></h2><p><strong>主料</strong></p><table tabindex="0"><thead><tr><th>用料</th><th>说明</th></tr></thead><tbody><tr><td>老鸭</td><td>剁 5cm 的块；老鸭汤更甜，但要多炖半小时</td></tr><tr><td>生姜</td><td></td></tr><tr><td>小葱</td><td></td></tr></tbody></table><p><strong>配料与调料</strong></p><table tabindex="0"><thead><tr><th>用料</th><th>说明</th></tr></thead><tbody><tr><td>热水</td><td>必须热水，冷水会让肉收紧</td></tr><tr><td>盐</td><td></td></tr><tr><td>冬瓜</td><td>可选，切 3cm 块</td></tr></tbody></table><h2 id="步骤" tabindex="-1">步骤 <a class="header-anchor" href="#步骤" aria-label="Permalink to &quot;步骤&quot;">​</a></h2><ol><li><p><strong>泡血水。</strong> 鸭块冷水泡 30 分钟，中途换两次水，泡到水不再发红。顺带把鸭屁股和尾部的脂腺剪掉，那块腥味最重。</p></li><li><p><strong>煮鸭块。</strong> 鸭块冷水下锅煮，水开后撇净浮沫，煮到用筷子能戳动即可，用<strong>温水</strong>冲干净。</p><figure class="recipe-shots"><img loading="lazy" src="'+r+'" alt="鸭块冷水下锅，水面浮起灰白浮沫"><img loading="lazy" src="'+c+'" alt="煮鸭块后用温水冲洗，水面干净"></figure></li><li><p><strong>干煸去腥。</strong> 锅不放油，可以使用炖汤上面的鸭油煸炒，加入姜、辣椒爆香，放入鸭块煸炒。</p><ul><li><p>不用额外去加油，使用原油足够，这样做出来不会很腻，还香。</p></li><li><p>煸炒的时候，多加点盐，这样才会保证鸭肉有味，汤又不会太咸。</p></li></ul><figure class="recipe-shots"><img loading="lazy" src="'+p+'" alt="鸭块皮朝下在锅里干煸，逼出鸭油"></figure></li><li><p><strong>最小火炖。</strong> 倒 之前煮好的鸭汤，没过鸭块两指，大火烧开立刻转最小火，让汤面保持微开、不翻滚，盖盖炖个半个小时左右。</p><figure class="recipe-shots"><img loading="lazy" src="'+n+'" alt="汤面只冒小泡，保持微开不翻滚"></figure></li><li><p><strong>下冬瓜。</strong> 冬瓜切 3cm 块下锅，再炖 15 分钟，炖到半透明就好。不放冬瓜就跳过这步，多炖 10 分钟。</p><figure class="recipe-shots"><img loading="lazy" src="'+g+'" alt="冬瓜块放进汤里，和鸭块一起炖"></figure></li><li><p><strong>调味出锅。</strong> 撒葱花。</p><figure class="recipe-shots"><img src="'+e+'" alt="俯拍特写：汤色清亮，鸭块、姜片与葱花"></figure></li></ol><h2 id="关键点" tabindex="-1">关键点 <a class="header-anchor" href="#关键点" aria-label="Permalink to &quot;关键点&quot;">​</a></h2><ul><li><strong>泡血水、焯水、干煸，三步各去一层腥</strong>：少一步，汤里就有鸭骚味。</li><li><strong>全程最小火</strong>：汤面只微微开。</li><li><strong>鸭油</strong>：使用鸭油煸炒，味美不油腻。</li><li><strong>加盐煸炒</strong>：加盐可以保证鸭肉有味，汤又不会太咸。</li></ul><p><a href="/life/recipes/">← 回菜谱总览</a></p>',13)])])}const x=s(h,[["render",u]]);export{y as __pageData,x as default};
